class Solution {
    public int rob(int[] nums) {
        int n = nums.length;
        if (n == 1) {
            return nums[0];
        }
        int excludeLast = robLine(nums, 0, n - 2);
        int excludeFirst = robLine(nums, 1, n - 1);
        return Math.max(excludeLast, excludeFirst);
    }

    private int robLine(int[] nums, int start, int end) {
        int twoHousesBack = 0;
        int oneHouseBack = 0;
        for (int i = start; i <= end; i++) {
            int current = Math.max(oneHouseBack, twoHousesBack + nums[i]);
            twoHousesBack = oneHouseBack;
            oneHouseBack = current;
        }
        return oneHouseBack;
    }
}

class Solution {
    public int rob(int[] nums) {
        int n = nums.length;
        if (n == 1) {
            return nums[0];
        }
        return Math.max(robTable(nums, 0, n - 2), robTable(nums, 1, n - 1));
    }

    private int robTable(int[] nums, int start, int end) {
        int length = end - start + 1;
        int[] dp = new int[length + 1];
        for (int offset = 1; offset <= length; offset++) {
            int money = nums[start + offset - 1];
            int skip = dp[offset - 1];
            int take = money + (offset >= 2 ? dp[offset - 2] : 0);
            dp[offset] = Math.max(skip, take);
        }
        return dp[length];
    }
}

import java.util.Arrays;

class Solution {
    public int rob(int[] nums) {
        int n = nums.length;
        if (n == 1) {
            return nums[0];
        }
        return Math.max(robRange(nums, 0, n - 2), robRange(nums, 1, n - 1));
    }

    private int robRange(int[] nums, int start, int end) {
        int[] memo = new int[nums.length];
        Arrays.fill(memo, -1);
        return bestFrom(nums, start, end, memo);
    }

    private int bestFrom(int[] nums, int index, int end, int[] memo) {
        if (index > end) {
            return 0;
        }
        if (memo[index] != -1) {
            return memo[index];
        }
        int skip = bestFrom(nums, index + 1, end, memo);
        int take = nums[index] + bestFrom(nums, index + 2, end, memo);
        memo[index] = Math.max(skip, take);
        return memo[index];
    }
}

class Solution {
    public int rob(int[] nums) {
        int n = nums.length;
        if (n == 1) {
            return nums[0];
        }
        int takeFirst = nums[0] + robLinear(nums, 2, n - 2);
        int skipFirst = robLinear(nums, 1, n - 1);
        return Math.max(takeFirst, skipFirst);
    }

    private int robLinear(int[] nums, int start, int end) {
        int twoHousesBack = 0;
        int oneHouseBack = 0;
        for (int i = start; i <= end; i++) {
            int current = Math.max(oneHouseBack, twoHousesBack + nums[i]);
            twoHousesBack = oneHouseBack;
            oneHouseBack = current;
        }
        return oneHouseBack;
    }
}

class Solution {
    public int rob(int[] nums) {
        int n = nums.length;
        if (n == 1) {
            return nums[0];
        }
        return Math.max(robStates(nums, 0, n - 2), robStates(nums, 1, n - 1));
    }

    private int robStates(int[] nums, int start, int end) {
        int robbed = Integer.MIN_VALUE / 4;
        int skipped = 0;
        for (int i = start; i <= end; i++) {
            int nextRobbed = skipped + nums[i];
            int nextSkipped = Math.max(skipped, robbed);
            robbed = nextRobbed;
            skipped = nextSkipped;
        }
        return Math.max(robbed, skipped);
    }
}
